function read(save) {
    const report = gamedataReport(save, data);
    const rows = report.tabs[0].views[0].rows;
    const row = (title) => rows.find((entry) => entry.title === title);
    // 190 chests placed in the game's stages (DreamWorld and empty pedestals excluded).
    const chests = gamedataRead(save, data).read("0x4766a777", "count");
    rows.push({ title: "Chests opened", done: chests, total: 190 });
    // The game counts these distances in metres.
    const metres = (m) => (m >= 1000 ? `${(m / 1000).toFixed(1)} km` : `${m} m`);
    const units = { "Distance travelled": metres, "Cucco flight": metres };
    for (const tab of report.tabs) {
        for (const view of tab.views) {
            for (const entry of view.rows) {
                if (units[entry.title] && typeof entry.value === "number") {
                    entry.value = units[entry.title](entry.value);
                }
            }
        }
    }
    // Bosses: defeated once the dungeon's reward (stone or medallion) is held, or its Heart
    // Container taken. The Heart Container keeps its own row, in case it was left behind.
    const reader = gamedataRead(save, data);
    const heartRows = report.tabs.find((tab) => tab.name === "Dungeons");
    let defeated = 0;
    for (const view of heartRows ? heartRows.views : []) {
        const boss = data.bosses[view.name];
        if (boss === undefined) {
            continue;
        }
        const heart = view.rows.find((entry) => entry.title === "Heart Containers");
        if (heart) {
            heart.title = "Heart Container";
        }
        const done = reader.read(boss.reward, "flag") !== 0 || (heart !== undefined && heart.done > 0);
        view.rows.push({ title: `Boss: ${boss.name}`, check: done });
        defeated += done ? 1 : 0;
        const score = rows.find((entry) => entry.title === view.name && entry.total !== undefined);
        if (score) {
            score.done += done ? 1 : 0;
            score.total += 1;
        }
    }
    rows.push({ title: "Bosses defeated", done: defeated, total: Object.keys(data.bosses).length });
    // Mini-bosses: a permanent flag, or for those the way to the boss requires, the boss's Heart Container.
    const table = gamedataRead(save, data);
    const hearts = data.collections[2].zones;
    const dungeons = report.tabs.find((tab) => tab.name === "Dungeons");
    for (const boss of data.minibosses) {
        const heart = hearts.find((zone) => zone.name === boss.dungeon);
        const done =
            boss.flags.some((hash) => table.read(hash, "flag") !== 0) ||
            table.count(boss.keys) > 0 ||
            (boss.after_boss && heart !== undefined && table.count(heart.keys) > 0);
        const view = dungeons && dungeons.views.find((entry) => entry.name === boss.dungeon);
        if (view) {
            view.rows.push({ title: boss.title, check: done });
        }
        const score = rows.find((entry) => entry.title === boss.dungeon && entry.total !== undefined);
        if (score) {
            score.done += done ? 1 : 0;
            score.total += 1;
        }
    }
    // Upgrades: each tier the save marks as owned (a non-zero count), and the gear owned. The
    // starting wallet, stick and nut capacities are not listed as tiers.
    const owned = (hash) => table.read(hash, "number") > 0;
    const upgradeRows = data.upgrades.map((upgrade) => ({
        title: upgrade.title,
        done: upgrade.hashes.filter(owned).length,
        total: upgrade.hashes.length,
    }));
    const gearRows = data.gear.map((item) => ({ title: item.title, check: owned(item.hash) }));
    const tiers = upgradeRows.reduce((sum, entry) => sum + entry.done, 0);
    const tierTotal = upgradeRows.reduce((sum, entry) => sum + entry.total, 0);
    rows.push({ title: "Upgrades", done: tiers, total: tierTotal });
    rows.push({ title: "Gear", done: gearRows.filter((entry) => entry.check).length, total: gearRows.length });
    const worldTab = report.tabs.find((tab) => tab.name === "World");
    if (worldTab) {
        worldTab.views.unshift({ name: "Gear", rows: gearRows });
        worldTab.views.unshift({ name: "Upgrades", rows: upgradeRows });
    }
    // Chest heart pieces: the save does not say which chests are open yet.
    const world = report.tabs.find((tab) => tab.name === "World");
    if (world) {
        const at = world.views.findIndex((view) => view.name.startsWith("Heart Pieces given"));
        world.views.splice(at + 1, 0, {
            name: "Heart Pieces in chests",
            rows: data.chest_heart_pieces.map((title) => ({ title: title, value: "chest" })),
        });
    }
    // Enemies: the game counts each enemy actor it saw defeated (DefeatedEnemyNum.<actor>);
    // variants of one enemy (respawning, per-dungeon, sizes) are added up under its name.
    const enemyRows = [];
    const bossRows = [];
    for (const enemy of data.enemies) {
        let count = 0;
        for (const hash of enemy.hashes) {
            count += Math.max(0, table.read(hash, "number"));
        }
        (enemy.boss ? bossRows : enemyRows).push({ title: enemy.title, value: count });
    }
    const byCount = (a, b) => b.value - a.value || (a.title < b.title ? -1 : 1);
    enemyRows.sort(byCount);
    bossRows.sort(byCount);
    const seen = enemyRows.filter((entry) => entry.value > 0);
    const stats = report.tabs.find((tab) => tab.name === "Stats");
    if (stats) {
        stats.views.push({
            name: "Enemies defeated by type",
            rows: [{ title: "Enemy types defeated", done: seen.length, total: enemyRows.length }]
                .concat(seen, enemyRows.filter((entry) => entry.value === 0)),
        });
        stats.views.push({ name: "Bosses defeated (times)", rows: bossRows });
    }
    report.tabs.push(timerTab());
    report.keys = [
        { title: "Skulltulas", value: row("Gold Skulltulas").done },
        { title: "Heart Pieces", value: row("Heart Pieces collected").value },
        { title: "Songs", value: row("Songs").done },
        { title: "Chests", value: `${chests} / 190` },
    ];
    return report;
}

// Dungeon and boss timers. The game keeps the zone and room it is in in a scene record: u32 room
// (-1 outside dungeons), -1, 0, a pointer to its own name at +0x18, the name's capacity (64),
// then the name. tick() finds the record once (Lichii searches the heap for the name), then
// reads it ten times a second while the game runs. Times add up across visits and sessions.
var timer = {
    zones: ["DodongoCavern", "DeathMountainTrail", "InsideTheDekuTree", "InsideJabuJabuBelly",
        "ForestTemple", "FireTemple", "WaterTemple", "ShadowTemple", "SpiritTemple",
        "BottomOfTheWell", "IceCavern", "GerudoTrainingGround", "InsideGanonCastle", "GanonCastle",
        "HyruleField", "KokiriForest", "LostWood", "SacredForestMeadow", "Market", "HyruleCastle",
        "KakarikoVillage", "Graveyard", "DeathMountainCrater", "GoronCity", "ZoraRiver",
        "ZoraDomain", "ZoraFountain", "GerudoValley", "GerudoFortress", "HountedWasteland",
        "DesertColossus", "SageRoom", "DreamWorld"],
    // boss: the boss's room; any: every room of the zone is the fight.
    dungeons: {
        InsideTheDekuTree: { name: "Great Deku Tree", boss: 10, title: "Gohma" },
        DodongoCavern: { name: "Dodongo Cavern", boss: 22, title: "King Dodongo" },
        InsideJabuJabuBelly: { name: "Lord Jabu-Jabu's Belly", boss: 15, title: "Barinade" },
        ForestTemple: { name: "Forest Temple", boss: 29, title: "Phantom Ganon" },
        FireTemple: { name: "Fire Temple", boss: 33, title: "Volvagia" },
        WaterTemple: { name: "Water Temple", boss: 23, title: "Morpha" },
        ShadowTemple: { name: "Shadow Temple", boss: 24, title: "Bongo Bongo" },
        SpiritTemple: { name: "Spirit Temple", boss: 33, title: "Twinrova" },
        BottomOfTheWell: { name: "Bottom of the Well" },
        IceCavern: { name: "Ice Cavern" },
        GerudoTrainingGround: { name: "Gerudo Training Ground" },
        InsideGanonCastle: { name: "Ganon's Castle", boss: 63, title: "Ganondorf" },
        GanonCastle: { name: "Ganon's Castle (collapse and Ganon)", any: true, title: "Ganon" },
    },
    // Plain names for the zones, and the mini-boss rooms, for the "Now" line.
    names: {"HyruleCastle": "Hyrule Castle", "GerudoFortress": "Gerudo Fortress", "LostWood": "Lost Woods", "DesertColossus": "Evil Desert Colossus", "DodongoCavern": "Dodongo Cavern", "HyruleField": "Hyrule Field", "BottomOfTheWell": "Bottom of the Well", "Graveyard": "Graveyard", "ZoraRiver": "Zora River", "HountedWasteland": "Mirage Desert", "IngoRanch": "Ingo Ranch", "SpiritTemple": "Spirit Temple", "GanonCastle": "Ganondorf's Castle", "KokiriForest": "Kokiri Forest", "ZoraFountain": "Zora Fountain", "ForestTemple": "Forest Temple", "GerudoTrainingGround": "Gerudo Proving Grounds", "InsideTheDekuTree": "Great Deku Tree", "IceCavern": "Ice Cavern", "KakarikoVillage": "Kakariko Village", "SacredForestMeadow": "Sacred Grove", "InsideJabuJabuBelly": "Lord Jabu-Jabu's Belly", "LakeHylia": "Lake Hylia", "TimeTemple": "Temple of Time", "WaterTemple": "Water Temple", "DreamWorld": "Hall of Fallen Foes", "InsideGanonCastle": "Inside Ganondorf's Castle", "FireTemple": "Fire Temple", "GerudoValley": "Gerudo Valley", "GoronCity": "Goron City", "LonLonRanch": "Lon Lon Ranch", "Market": "Hyrule Castle Town", "ShadowTemple": "Shadow Temple", "DeathMountainCrater": "Death Mountain Crater", "DeathMountainTrail": "Death Mountain Trail", "ZoraDomain": "Zora Domain", "SageRoom": "Chamber of Sages"},
    minis: {
        DodongoCavern: { 5: "Lizalfos", 16: "Lizalfos" },
        InsideJabuJabuBelly: { 6: "Big Octo" },
        ForestTemple: { 2: "Poes" },
        FireTemple: { 3: "Flare Dancer", 24: "Flare Dancer" },
        WaterTemple: { 22: "Dark Link" },
        SpiritTemple: { 32: "Iron Knuckle" },
    },
    file: "0400486024DEC000-timers.json",
    // The record's address and the last place, so a reloaded module (or the next launch, which
    // usually starts where the last one stopped) finds the record at once.
    sceneFile: "0400486024DEC000-scene.json",
    order: null,
    address: null,
    next: 0,
    last: 0,
    times: null,
    unsaved: 0,
    drawn: 0,
    where: "",
};

function timerTimes() {
    if (timer.times === null) {
        try {
            timer.times = JSON.parse(notes.load(timer.file) || "{}");
        } catch (error) {
            timer.times = {};
        }
    }
    return timer.times;
}

function hexText(text) {
    let out = "";
    for (let i = 0; i < text.length; ++i) {
        out += text.charCodeAt(i).toString(16).padStart(2, "0");
    }
    return out;
}

/// The scene record at address (a number), or null when it is not one.
function sceneAt(address) {
    const bytes = notes.memory("0x" + address.toString(16), 0x58);
    if (!bytes) {
        return null;
    }
    const view = new DataView(bytes);
    const pointer = view.getUint32(0xc, true) + view.getUint32(0x10, true) * 4294967296;
    if (view.getUint32(4, true) !== 0xffffffff || view.getUint32(0x14, true) !== 0x40 ||
        pointer !== address + 0x18) {
        return null;
    }
    let zone = "";
    for (let i = 0x18; i < 0x58 && view.getUint8(i) !== 0; ++i) {
        zone += String.fromCharCode(view.getUint8(i));
    }
    return { zone: zone, room: view.getInt32(0, true) };
}

function rememberScene(zone) {
    notes.store(timer.sceneFile, JSON.stringify({ address: timer.address, zone: zone }));
}

/// Where the game is, or null while the record is being looked for.
function scene() {
    if (timer.order === null) {
        // First the address and place remembered, then every zone.
        let saved = {};
        try {
            saved = JSON.parse(notes.load(timer.sceneFile) || "{}");
        } catch (error) {
            saved = {};
        }
        if (typeof saved.address === "number") {
            timer.address = saved.address;
        }
        timer.order = timer.zones.slice();
        if (saved.zone && timer.order.indexOf(saved.zone) >= 0) {
            timer.order.splice(timer.order.indexOf(saved.zone), 1);
            timer.order.unshift(saved.zone);
        }
    }
    if (timer.address !== null) {
        const found = sceneAt(timer.address);
        if (found) {
            return found;
        }
        timer.address = null;
    }
    // One zone name at a time: Lichii searches on its own thread and answers null until done.
    const zone = timer.order[timer.next % timer.order.length];
    const hits = notes.search("40000000" + hexText(zone) + "00");
    if (hits === null) {
        return null;
    }
    for (const hit of hits) {
        const address = parseInt(hit, 16) - 0x14;
        const found = sceneAt(address);
        if (found) {
            timer.address = address;
            rememberScene(found.zone);
            return found;
        }
    }
    timer.next += 1;
    return null;
}

function tick() {
    const now = Date.now();
    // A gap well over the usual spacing of ticks (100 ms with Lichii next13, 1 s before) means
    // the emulator was paused or stalled: it is not counted. The spacing is averaged as it runs.
    const gap = timer.last === 0 ? Infinity : now - timer.last;
    timer.last = now;
    if (gap < 2000) {
        timer.spacing = timer.spacing === undefined ? gap : timer.spacing * 0.9 + gap * 0.1;
    }
    const limit = Math.max(300, 3 * (timer.spacing === undefined ? 1000 : timer.spacing));
    const step = gap > limit ? 0 : gap / 1000;
    const here = scene();
    if (here === null) {
        return false;
    }
    // During a load the record has no name yet: the time goes to the zone being left.
    if (here.zone === "") {
        if (!timer.zone) {
            return false;
        }
        here.zone = timer.zone;
        here.room = -1;
    }
    const where = describe(here);
    const moved = where !== timer.where;
    if (moved && here.zone !== timer.zone) {
        timer.zone = here.zone;
        rememberScene(here.zone);
    }
    timer.where = where;
    // Every zone has its time ("dungeon" is the zone's total, dungeon or not), bosses their room's.
    const dungeon = timer.dungeons[here.zone];
    const times = timerTimes();
    const entry = times[here.zone] || (times[here.zone] = { dungeon: 0, boss: 0 });
    entry.dungeon += step;
    if (dungeon && (dungeon.any || (dungeon.boss !== undefined && here.room === dungeon.boss))) {
        entry.boss += step;
    }
    timer.unsaved += step;
    if (moved || timer.unsaved >= 10) {
        return flushTimes();
    }
    // The panel shows the running times once a second; the file is written every 10 seconds.
    if (now - timer.drawn >= 1000) {
        timer.drawn = now;
        return true;
    }
    return false;
}

/// A zone's plain name; the child and adult versions of a place keep their own times.
function placeName(zone) {
    const age = /^(.*?)_(Child|Adult)(_.*)?$/.exec(zone);
    if (age && timer.names[age[1]]) {
        return `${timer.names[age[1]]} (${age[2].toLowerCase()})`;
    }
    return timer.names[zone] || zone;
}

/// "Dodongo Cavern · room 22 · boss: King Dodongo", "Kakariko Village".
function describe(here) {
    let text = placeName(here.zone);
    if (here.room < 0) {
        return text;
    }
    text += ` · room ${here.room}`;
    const dungeon = timer.dungeons[here.zone];
    const mini = timer.minis[here.zone] && timer.minis[here.zone][here.room];
    if (dungeon && (dungeon.any || dungeon.boss === here.room)) {
        text += ` · boss: ${dungeon.title}`;
    } else if (mini) {
        text += ` · mini-boss: ${mini}`;
    }
    return text;
}

function flushTimes() {
    notes.store(timer.file, JSON.stringify(timerTimes()));
    timer.unsaved = 0;
    return true;
}

/// h:mm:ss.t, or m:ss.t under an hour.
function clock(seconds) {
    const tenths = Math.floor(seconds * 10);
    const total = Math.floor(tenths / 10);
    const h = Math.floor(total / 3600);
    const m = String(Math.floor((total % 3600) / 60)).padStart(2, "0");
    const s = String(total % 60).padStart(2, "0");
    const t = tenths % 10;
    return h > 0 ? `${h}:${m}:${s}.${t}` : `${Math.floor(total / 60)}:${s}.${t}`;
}

function timerTab() {
    const times = timerTimes();
    const dungeonRows = [];
    const bossRows = [];
    for (const zone of Object.keys(timer.dungeons)) {
        const dungeon = timer.dungeons[zone];
        const entry = times[zone] || { dungeon: 0, boss: 0 };
        if (!dungeon.any) {
            dungeonRows.push({ title: dungeon.name, value: entry.dungeon > 0 ? clock(entry.dungeon) : "-" });
        }
        if (dungeon.title) {
            bossRows.push({ title: dungeon.title, value: entry.boss > 0 ? clock(entry.boss) : "-" });
        }
    }
    const placeRows = Object.keys(times)
        .filter((zone) => zone !== "" && times[zone].dungeon >= 1)
        .sort((a, b) => times[b].dungeon - times[a].dungeon)
        .map((zone) => ({ title: placeName(zone), value: clock(times[zone].dungeon) }));
    // Where the game is, once the scene record is found.
    const tracking = timer.address === null ? [] : [{ title: "Now", value: timer.where }];
    return {
        name: "Timers",
        views: [
            { name: "Time in dungeons", rows: tracking.concat(dungeonRows) },
            { name: "Time in boss rooms", rows: bossRows },
            { name: "Time by place", rows: tracking.concat(placeRows) },
        ],
    };
}
